// A real Android app that calls a C library through JNI bindings generated by the plugin.
// Both plugins are applied to this one module: the konan plugin produces the .a, the JNI stub .so and the
// Kotlin bindings; AGP packages the .so and compiles the app.

import org.jetbrains.kotlin.konan.target.KonanTarget

plugins {
    id("com.android.application") // AGP 9 has built-in Kotlin support
    id("io.github.lemcoder.konanplugin")
}

konan {
    // native/*.c -> one static archive per ABI: device + emulator.
    val mymath = libraries.create("mymath") { targets(KonanTarget.ANDROID_ARM64, KonanTarget.ANDROID_X64) }
    // An Android app gets JNI bindings, wired into its variants, and a JNI library per ABI the library
    // is built for, packaged as jniLibs.
    bindings {
        create("mymath") {
            defFile.set(file("src/main/nativeInterop/mymath.def"))
            includeDirs.from("native")
            library(mymath)
        }
    }
}

android {
    namespace = "com.example.jniapp"
    compileSdk = 36

    defaultConfig {
        applicationId = "com.example.jniapp"
        minSdk = 21          // matches the NDK __ANDROID_API__=21 the stubs are built against
        targetSdk = 36
        versionCode = 1
        versionName = "1.0"
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

// That's it — the plugin wires the generated Kotlin bindings and per-ABI jniLibs into AGP and orders
// compileNativeLibraryMymath / generateJniMymath / linkJniMymath before the build.
